@staticmethod
def _presentation_request_payload(
    record: PresentationRequestRecord,
) -> Dict[str, Any]:
    """按对外契约组装展示请求对象。

    固定键序：request_id、challenge、expires_at、disclose、
    issuer_dids（不限定时为 null）、holder_binding、status
    （pending/consumed/cancelled）；已消费时末尾追加
    consumed_at 与 consumed_presentation_id；已取消时末尾追加
    cancel_reason 与 cancelled_at（不含任何消费字段）。
    """
    payload: Dict[str, Any] = {
        "request_id": record.request_id,
        "challenge": record.challenge,
        "expires_at": record.expires_at,
        "disclose": record.disclose,
        "issuer_dids": record.issuer_dids,
        "holder_binding": record.holder_binding,
        "status": record.status,
    }
    if record.status == "consumed":
        payload["consumed_at"] = record.consumed_at
        payload["consumed_presentation_id"] = (
            record.consumed_presentation_id
        )
    elif record.status == "cancelled":
        payload["cancel_reason"] = record.cancel_reason
        payload["cancelled_at"] = record.cancelled_at
    return payload

def _post_presentation_request(self, tenant: str) -> None:
    # POST /v1/presentation-requests：验证方发起展示请求。
    # 请求体恰含非空 challenge（≤256 码点）与可选 expires_in
    # （非布尔整数 1..86400，缺省 300）、disclose（数组，RFC6901
    # claims 叶子：禁根、重复与祖先重叠；缺省空列表=零披露）、
    # issuer_dids（非空字符串数组，省略/null 为不限定，显式
    # 空列表为空白名单）、
    # holder_binding（布尔，缺省 false）。多余字段或类型非法一律
    # 400。成功 201 返回请求对象（status=pending）。
    data = self._read_json()
    if "challenge" not in data:
        raise ValidationError("缺少字段: challenge")
    extra = sorted(
        set(data)
        - {
            "challenge", "expires_in", "disclose",
            "issuer_dids", "holder_binding",
        }
    )
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    challenge = data["challenge"]
    if not isinstance(challenge, str) or not challenge:
        raise ValidationError("字段 challenge 必须为非空字符串")
    if len(challenge) > 256:
        raise ValidationError(
            "字段 challenge 按 Unicode 码点不能超过 256"
        )
    expires_in = None
    if "expires_in" in data:
        expires_in = data["expires_in"]
        if not isinstance(expires_in, int) or isinstance(
            expires_in, bool
        ):
            raise ValidationError("字段 expires_in 必须为整数")
        if not 1 <= expires_in <= 86400:
            raise ValidationError(
                "字段 expires_in 须在 1 到 86400 之间"
            )
    disclose = None
    if "disclose" in data:
        disclose = data["disclose"]
    issuer_dids = None
    if "issuer_dids" in data:
        issuer_dids = data["issuer_dids"]
    holder_binding = False
    if "holder_binding" in data:
        holder_binding = data["holder_binding"]
        if not isinstance(holder_binding, bool):
            raise ValidationError("字段 holder_binding 必须为布尔值")
    record = store.create_presentation_request(
        tenant,
        challenge=challenge,
        expires_in=expires_in,
        disclose=disclose,
        issuer_dids=issuer_dids,
        holder_binding=holder_binding,
    )
    self._send_json(
        201, self._presentation_request_payload(record)
    )

def _get_presentation_request(
    self, tenant: str, request_id: str
) -> None:
    # GET /v1/presentation-requests/{request_id}：查询本租户展示
    # 请求；未知 ID（含他租户同 ID）一律 404。
    if not request_id:
        raise ValidationError("路径缺少 request_id")
    record = store.get_presentation_request(tenant, request_id)
    self._send_json(
        200, self._presentation_request_payload(record)
    )

def _post_cancel_presentation_request(
    self, tenant: str, request_id: str
) -> None:
    # POST /v1/presentation-requests/{request_id}/cancel：
    # 验证方主动取消展示请求（终态，不可恢复）。请求体为空对象
    # 或仅含 reason；空体、非法 JSON、非对象、多余字段或非法
    # reason 一律 400。先校验租户头与请求体，再查资源；未知或
    # 他租户请求 404，已消费 409。pending（含已过期）首次取消
    # 200，状态保存为 cancelled，响应在查询对象上追加
    # cancel_reason 与 cancelled_at。有效重复取消幂等返回首次
    # 结果（忽略本次 reason）。
    if not request_id:
        raise ValidationError("路径缺少 request_id")
    # 取消入口错误响应仅含非空中文 error，故不复用带英文解析
    # 细节的 _read_json：空体/非法 JSON/非对象均给纯中文文案。
    length = int(self.headers.get("Content-Length") or 0)
    raw = self.rfile.read(length) if length else b""
    if not raw:
        raise ValidationError("请求体不能为空，须为空对象或取消原因对象")
    try:
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValidationError("请求体不是合法的 JSON 对象") from None
    if not isinstance(data, dict):
        raise ValidationError("请求体必须为 JSON 对象")
    extra = sorted(set(data) - {"reason"})
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    if "reason" in data:
        reason = data["reason"]
        if not isinstance(reason, str):
            raise ValidationError("字段 reason 必须为字符串")
        reason = reason.strip()
        if not reason:
            raise ValidationError("字段 reason 裁剪后不能为空")
        if len(reason) > 256:
            raise ValidationError(
                "字段 reason 按 Unicode 码点不能超过 256"
            )
    else:
        reason = REASON_UNSET
    record = store.cancel_presentation_request(
        tenant, request_id, reason
    )
    self._send_json(
        200, self._presentation_request_payload(record)
    )

@staticmethod
def _validate_present_item(
    item: Any, index: int
) -> Dict[str, Any]:
    """校验单个演示生成项，返回透传给 store 的关键字参数。

    规则与单项 present 完全一致：项须为对象，恰含 disclose 及
    可选 challenge、expires_in、holder_binding；challenge 为非空
    字符串且按 Unicode 码点不超过 256；expires_in 为非布尔整数
    且在 1..86400；holder_binding 为布尔。index 为从 0 起的项
    序号，错误信息带从 1 起的中文项号。
    """
    where = f"第 {index + 1} 项"
    if not isinstance(item, dict):
        raise ValidationError(f"{where}必须为 JSON 对象")
    if "disclose" not in item:
        raise ValidationError(f"{where}缺少字段: disclose")

